cd D:/the-synaptic-sea-2d/design/gdd; cat > /tmp/ed.pl <<'E'
undef $/; $_=<STDIN>;
my $n=0;
$n+= s/GIVEN `hud_tuning` data WHEN validated THEN every knob outside its Tuning Knobs safe range fails \(including `PROMPT_MIN_CYCLE_TICKS` below 20, `HONEST_TICK_MS` other than 500, infeasible at the live `BEACON_SWEEP_TICKS`, or `u` other than 1 \(see AC-HS-73\), `HUD_SETTLE_MS` outside 250-400, `BAR_LEN_\*` out of 12-64 or not ordered S < M < L, `BAR_STROKE_PX` below 2, `MARK_DUTY_PM` outside 400-600, `FLASH_AREA_EXEMPT_PM` outside 50-100\) \*\(Amended 2026-10-27 — user rulings\)\*,/GIVEN `hud_tuning` data WHEN loaded at boot THEN boot fails with `CONTENT_INVARIANT(table, name)` for each named structural invariant violated (`PROMPT_MIN_CYCLE_TICKS` below 20, `HONEST_TICK_MS` other than 500, infeasible at the live `BEACON_SWEEP_TICKS`, or `u` other than 1 (see AC-HS-73), `BAR_LEN_*` not ordered S < M < L, `FLASH_AREA_EXEMPT_PM` above 100) *(Amended 2026-10-27 — user rulings)*; GIVEN a knob outside its published Tuning Knobs range that violates no named invariant (`HUD_SETTLE_MS` outside 250-400, `BAR_LEN_*` out of 12-64, `BAR_STROKE_PX` below 2, `MARK_DUTY_PM` outside 400-600, `FLASH_AREA_EXEMPT_PM` below 50, `PROMPT_MIN_CYCLE_TICKS` above 40) THEN boot succeeds and the CI range diff against `tests\/fixtures\/hud\/safe_ranges.json` reports it (ADVISORY, guidance not a boot assertion) *(Amended 2026-10-29 — ADR-0007 sync, § 2.5)*;/ or die "no 123";
$n+= s/and any `u` other than 1 fails data validation \(the edge unit/and any `u` other than 1 fails boot with `CONTENT_INVARIANT` *(Amended 2026-10-29 — ADR-0007 sync, § 2.5)* (the edge unit/ or die "no 73a";
$n+= s/fails data validation\. \(D\.2\) \*\(Amended 2026-10-27 — design review\)\*/fails boot with `CONTENT_INVARIANT` *(Amended 2026-10-29 — ADR-0007 sync, § 2.5)*. (D.2) *(Amended 2026-10-27 — design review)*/ or die "no 73b";
print; print STDERR "$n\n";
E
perl /tmp/ed.pl < hud-and-suit-layer.md > /tmp/out.md && wc -c hud-and-suit-layer.md /tmp/out.md

